// MARK: CSS
import "./App.css";

import { useEffect } from "react";

// MARK: Core
import Lenis from "lenis";
import Cursor from "./core/Cursor";
import ScrollToTop from "../core/ScrollToTop";

// MARK: Router
import {
    BrowserRouter,
    Routes,
    Route
} from "react-router-dom";

// MARK: Pages
import HomePage from "./pages/HomePage";
import ProjectsPage from "./pages/ProjectsPage";

function App() {
    useEffect(() => {
        const lenis = new Lenis({
            duration: 1.2,
            smoothWheel: true,
            smoothTouch: false,
        });
        function raf(time) {
            lenis.raf(time);
            requestAnimationFrame(raf);
        }
        requestAnimationFrame(raf);
        return () => {
            lenis.destroy();
        };
    }, []);
    return (
        <BrowserRouter>
            <ScrollToTop />
            <Cursor />
            <Routes>
                <Route
                    path="/"
                    element={<HomePage/>}
                />
                <Route
                  path="/projects/:slug"
                  element={<ProjectsPage/>}

                />
            </Routes>
        </BrowserRouter>
    );

}

export default App;
